SELECT * FROM ( SELECT A.* , (SELECT USER_ID FROM TB_USER U WHERE U.DEL_YN = 'N' AND U.USER_SEQ = A.REG_USER_SEQ) USER_ID FROM TB_BOARD A WHERE A.DEL_YN = 'N' AND A.USE_YN = 'Y' ) TB
TB.BOARD_TP = #{type}
AND BOARD_NM LIKE CONCAT('%', #{keyword}, '%')
AND BOARD_SMP_DERPN LIKE CONCAT('%', #{keyword}, '%')
AND USER_ID LIKE CONCAT('%', #{keyword}, '%')
/*||ORDER BY REG_DT DESC||*/

SELECT * FROM ( SELECT A.* , (SELECT USER_ID FROM TB_USER U WHERE U.DEL_YN = 'N' AND U.USER_SEQ = A.REG_USER_SEQ) USER_ID FROM TB_BOARD A WHERE A.DEL_YN = 'N' AND A.USE_YN = 'Y' AND (A.REG_USER_SEQ = #{user_seq} OR A.RLS_YN = 'Y') ) TB
TB.BOARD_TP = #{type}
AND BOARD_NM LIKE CONCAT('%', #{keyword}, '%')
AND BOARD_SMP_DERPN LIKE CONCAT('%', #{keyword}, '%')
AND USER_ID LIKE CONCAT('%', #{keyword}, '%')
/*||ORDER BY REG_DT DESC||*/
